using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.FNZ.Cuentas;using GraphApi.Services.FNZ.Cuentas;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.FNZ.Cuentas{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Cuentas: creación, actualización y eliminación.")]    public class CuentasMutation    {        [Authorize]        [GraphQLName("createCuentas")]        [GraphQLDescription("Crea un nuevo Cuenta usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadCuentas> CreateCuentasAsync(            [GraphQLDescription("Datos necesarios para crear el Cuenta.")]            clCreateCuentas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Cuenta.")]            ICuentasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateCuentas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateCuentas")]        [GraphQLDescription("Actualiza los campos especificados de un Cuenta existente.")]        public async Task<clReadCuentas?> UpdateCuentasAsync(            [GraphQLDescription("Datos del Cuenta a actualizar.")]            clUpdateCuentas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Cuenta.")]            ICuentasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateCuentas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteCuentas")]        [GraphQLDescription("Elimina un Cuenta por su ID.")]        public async Task<bool> delCuentasAsync(            [GraphQLDescription("ID del Cuenta a eliminar.")]            int nCuentasID,            [Service]            [GraphQLDescription("Servicio para operaciones de Cuenta.")]            ICuentasService objService        )        {            return await objService.DeleteCuentas(nCuentasID);        }    }}